def runcode(self, code):
    async def _runcode_in_trio():
        func = types.FunctionType(code, self.locals)
        if inspect.iscoroutinefunction(func):
            return await outcome.acapture(func)
        return outcome.capture(func)

    try:
        trio.from_thread.run(_runcode_in_trio).unwrap()
    except BaseException as exc:  # noqa: B036
        # We use this to strip the frames of the coroutine machinery
        # and just show the frame in the repl.
        raise exc.with_traceback(exc.__traceback__.tb_next)
