cd /workspace && python - <<'EOF'
import sys, traceback, types, outcome
import trio

code = compile("raise BaseException", "<console>", "single")
async def _run():
    func = types.FunctionType(code, {})
    return outcome.capture(func)

async def main():
    await trio.to_thread.run_sync(sync_part)

def sync_part():
    try:
        trio.from_thread.run(_run).unwrap()
    except BaseException as exc:
        tb = exc.__traceback__
        while tb is not None and tb.tb_frame.f_code.co_filename != "<console>":
            tb = tb.tb_next
        exc.__traceback__ = tb
        traceback.print_exception(type(exc), exc, sys.exc_info()[2])
trio.run(main)
EOF
